questionvariables.text:
/* Design: classify pattern: three categories in a fixed order; option values are unique per dropdown (10k + category). Each variant uses a curated set drawn from a pool. Source: original. */
keys: [1,2,2,3,1,1,2,3,1,2,1,2,3,1];
sets: [[1,2,4,9,12],[3,5,8,10,14],[2,6,7,13,11],[4,9,12,1,3],[5,2,13,7,6],[8,14,10,11,2],[1,4,7,12,5],[13,3,9,6,10],[14,8,2,5,7],[11,10,4,3,1]];
ix: 1+rand(10);
S: random_permutation(sets[ix]);
kk: makelist(keys[S[k]], k, 1, 5);
it1: S[1];
opt1: [[11, is(kk[1]=1), "a great circle"], [12, is(kk[1]=2), "a small circle"], [13, is(kk[1]=3), "half of a great circle"]];
ta1: 10+kk[1];
wr1: 10+mod(kk[1],3)+1;
it2: S[2];
opt2: [[21, is(kk[2]=1), "a great circle"], [22, is(kk[2]=2), "a small circle"], [23, is(kk[2]=3), "half of a great circle"]];
ta2: 20+kk[2];
wr2: 20+mod(kk[2],3)+1;
it3: S[3];
opt3: [[31, is(kk[3]=1), "a great circle"], [32, is(kk[3]=2), "a small circle"], [33, is(kk[3]=3), "half of a great circle"]];
ta3: 30+kk[3];
wr3: 30+mod(kk[3],3)+1;
it4: S[4];
opt4: [[41, is(kk[4]=1), "a great circle"], [42, is(kk[4]=2), "a small circle"], [43, is(kk[4]=3), "half of a great circle"]];
ta4: 40+kk[4];
wr4: 40+mod(kk[4],3)+1;
it5: S[5];
opt5: [[51, is(kk[5]=1), "a great circle"], [52, is(kk[5]=2), "a small circle"], [53, is(kk[5]=3), "half of a great circle"]];
ta5: 50+kk[5];
wr5: 50+mod(kk[5],3)+1;
